s=p.read_text()
s=s.replace(' const [notice,setNotice]=useState("");', ' const [notice,setNotice]=useState("");\n const [editOpen,setEditOpen]=useState(false);\n const [historyOpen,setHistoryOpen]=useState(false);\n const [editForm,setEditForm]=useState({name:"",phone:"",business:"",city:"",address:"",status:"غیر ثابت" as CustomerStatus,note:""});')
s=s.replace(' const promote=async(id:number)=>{await updateCustomer.mutateAsync({id,data:{status:"ثابت"}});await utils.crm.customers.invalidate();setNotice("مشتری به فهرست مشتریان ثابت اضافه شد.");};', ' const promote=async(id:number)=>{await updateCustomer.mutateAsync({id,data:{status:"ثابت"}});await utils.crm.customers.invalidate();setNotice("مشتری به فهرست مشتریان ثابت اضافه شد.");};\n const openEdit=()=>{if(!selected)return;setEditForm({name:selected.name,phone:selected.phone,business:selected.business,city:selected.city,address:selected.address,status:selected.status,note:selected.note||""});setEditOpen(true);};\n const saveEdit=async(event:React.FormEvent)=>{event.preventDefault();if(!selected)return;await updateCustomer.mutateAsync({id:selected.id,data:editForm});await utils.crm.customers.invalidate();setEditOpen(false);setNotice("اطلاعات مشتری با موفقیت ویرایش شد.");};')
s=s.replace(' return <div className="sales-page">', ' return <div className="sales-page">{editOpen&&<div className="customer-modal-backdrop"><form className="customer-modal" onSubmit={saveEdit}><div className="customer-modal-head"><div><span className="eyebrow">دفتر مشتریان</span><h2>ویرایش اطلاعات مشتری</h2><p>تغییرات مستقیماً در پرونده همین مشتری ذخیره می‌شود.</p></div><button type="button" className="modal-close" onClick={()=>setEditOpen(false)}>×</button></div><div className="form-grid two"><label>نام شخص<input required value={editForm.name} onChange={e=>setEditForm({...editForm,name:e.target.value})}/></label><label>شماره موبایل<input required value={editForm.phone} onChange={e=>setEditForm({...editForm,phone:e.target.value})}/></label><label>نام شرکت / فروشگاه<input value={editForm.business} onChange={e=>setEditForm({...editForm,business:e.target.value})}/></label><label>شهر / استان<input value={editForm.city} onChange={e=>setEditForm({...editForm,city:e.target.value})}/></label><label>وضعیت مشتری<select value={editForm.status} onChange={e=>setEditForm({...editForm,status:e.target.value as CustomerStatus})}><option>ثابت</option><option>غیر ثابت</option><option>نیاز به پیگیری</option><option>در حال پیگیری</option></select></label><label className="span-two">آدرس کامل<input value={editForm.address} onChange={e=>setEditForm({...editForm,address:e.target.value})}/></label><label className="span-two">یادداشت فروش<textarea value={editForm.note} onChange={e=>setEditForm({...editForm,note:e.target.value})}/></label></div><div className="modal-actions"><button type="button" className="outline-button" onClick={()=>setEditOpen(false)}>انصراف</button><button type="submit" className="primary-button">ذخیره تغییرات</button></div></form></div>}{historyOpen&&selected&&<div className="customer-modal-backdrop"><div className="customer-modal history-modal"><div className="customer-modal-head"><div><span className="eyebrow">تاریخچه واقعی سفارش‌ها</span><h2>سوابق خرید {selected.name}</h2><p>تمام سفارش‌های متصل به این مشتری از دیتابیس نمایش داده می‌شود.</p></div><button type="button" className="modal-close" onClick={()=>setHistoryOpen(false)}>×</button></div><div className="history-modal-list">{orders.filter(o=>o.customerId===selected.id).map((order,i)=>{let items:any[]=[];try{items=JSON.parse(order.itemsJson)}catch{}return <article className="history-modal-item" key={order.id}><div><strong>خرید {(i+1).toLocaleString("fa-IR")} · سفارش #{order.id}</strong><span>{order.jalaliDate} · وضعیت: {order.status==="delivered"?"تحویل داده شده":"در انتظار تحویل"}</span><p>{items.map(item=>`${item.product||"محصول"} (${item.qty||0} عدد)`).join("، ")||"اقلام سفارش ثبت شده"}</p></div><b>{money(order.total)}</b></article>})}{!orders.some(o=>o.customerId===selected.id)&&<div className="empty-mini">برای این مشتری هنوز سفارش ثبت‌شده‌ای وجود ندارد.</div>}</div></div></div>}')
s=s.replace('<button className="icon-button"><Edit3 size={17}/></button>', '<button className="icon-button" onClick={openEdit} aria-label="ویرایش مشتری"><Edit3 size={17}/></button>')
s=s.replace('<div className="section-title"><div><History size={16}/><strong>تاریخچه خرید</strong></div><span>{orders.filter(o=>o.customerId===selected.id).length.toLocaleString("fa-IR")} خرید</span></div>', '<div className="section-title"><div><History size={16}/><strong>تاریخچه خرید</strong></div><button className="text-button" onClick={()=>setHistoryOpen(true)}>مشاهده کامل</button><span>{orders.filter(o=>o.customerId===selected.id).length.toLocaleString("fa-IR")} خرید</span></div>')
